CREATE DATABASE IF NOT EXISTS rblx08 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rblx08;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(20) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,description TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS catalog_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,description TEXT NULL,item_type ENUM('hat','face','shirt','pants','gear','other') NOT NULL DEFAULT 'other',price INT UNSIGNED NOT NULL DEFAULT 0,image_path VARCHAR(255) NULL,creator_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_catalog_type(item_type),CONSTRAINT fk_catalog_creator FOREIGN KEY(creator_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,acquired_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_inventory_user_item(user_id,item_id),CONSTRAINT fk_inventory_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_inventory_item FOREIGN KEY(item_id) REFERENCES catalog_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS games(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,description TEXT NULL,creator_id BIGINT UNSIGNED NULL,thumbnail_path VARCHAR(255) NULL,visits BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_games_creator FOREIGN KEY(creator_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS forum_topics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,replies_count INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_forum_created(created_at),CONSTRAINT fk_topics_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS forum_replies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_replies_topic(topic_id),CONSTRAINT fk_replies_topic FOREIGN KEY(topic_id) REFERENCES forum_topics(id) ON DELETE CASCADE,CONSTRAINT fk_replies_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT INTO catalog_items(name,description,item_type,price) SELECT 'Classic Red Baseball Cap','Sample item; replace with verified archive data.','hat',25 WHERE NOT EXISTS(SELECT 1 FROM catalog_items WHERE name='Classic Red Baseball Cap');
INSERT INTO games(name,description) SELECT 'Welcome to the Revival','Sample place entry for testing.' WHERE NOT EXISTS(SELECT 1 FROM games WHERE name='Welcome to the Revival');
